/**
 * App emission (M2, plan §4.3): `appToTf` consumes the discovered
 * `DeployableEntity` (the handle-form `app` compose body) and emits
 * `elementum_app` + one field resource per custom field (the field pass
 * delegates to `entities/field/to-tf.ts`).
 *
 * Dialect invariants:
 *  1. structured TfBlocks through src/engine/tf render — no string
 *     concatenation;
 *  2. BARE labels derived from bag keys via the tsLabel bijection (the
 *     stable naming contract); org data refs derive the same way from
 *     org.ts keys;
 *  3. ei's exact dialect shapes (status_options items carry `tags` always).
 * Unsupported authoring shapes degrade through `diagnostics` — reported,
 * never silent, never thrown (plan §4.3).
 */
import { workspaceAspectKey } from "../../engine/build/context.js";
import { DEPLOY_DEFAULT_STATUS_OPTION_VALUES, SYSTEM_FIELD_HCL_KEY_BY_KEY, SYSTEM_FIELD_KEY_BY_TAG } from "../../core/system-fields.js";
import { EntityTfError } from "../../engine/entity.js";
import { expr, snakeSlug } from "../../engine/tf/index.js";
import { accessPolicyToTf } from "../access-policy/to-tf.js";
import { dashboardsToTf } from "../dashboard/to-tf.js";
import { picklistLabel } from "../field/options.js";
import { dynamicLayoutsToTf } from "../dynamic-layout/to-tf.js";
import { fieldToTf } from "../field/to-tf.js";
import { SUB_TYPE_BY_TYPE_KEY } from "../field/types.js";
import { CATEGORY_ORG_BAG } from "../org/category.js";
import { categoryIdExpr, missingCategoryDiagnostic } from "../org/category-ref.js";
import { CLOUD_LINK_ORG_BAG } from "../org/cloud-link.js";
import { recordCreateFormToTf } from "../record-create-form/to-tf.js";
import { relationshipsToTf } from "../relationship/to-tf.js";
import { rolesToTf } from "../role/to-tf.js";
import { serviceAccountsToTf } from "../service-account/to-tf.js";
import { relationshipTargetsFromBag, widgetsToTf } from "../widget/to-tf.js";
import { viewToTf } from "../view/to-tf.js";
import { APP_RESOURCE_TYPE } from "./module.js";
/** System-field tags that fold into the app resource instead of emitting a field resource. */
export const SYSTEM_FIELD_TAGS = new Set([
    "TITLE",
    "HANDLE",
    "STATUS",
    "STAGE",
    "CREATED_AT",
    "CREATED_BY",
    "UPDATED_AT",
    "UPDATED_BY",
    "CLOSED_AT",
    "CLOSED_BY",
]);
/** Audit tags the provider auto-creates with fixed names (no rename attribute). */
const AUDIT_DEFAULT_NAMES = {
    CREATED_AT: "Created At",
    CREATED_BY: "Created By",
    UPDATED_AT: "Updated At",
    UPDATED_BY: "Updated By",
    CLOSED_AT: "Closed At",
    CLOSED_BY: "Closed By",
};
/** `elementum_app` + one field resource per custom field, in ei's dialect. */
export function appToTf(entity, ctx) {
    if (entity.kind !== "app") {
        throw new EntityTfError(`appToTf expects kind "app"; got "${entity.kind}" (refName "${entity.refName}")`);
    }
    const payload = entity.payload;
    if (payload === null || typeof payload !== "object") {
        throw new EntityTfError(`app "${entity.refName}" has a non-object payload`);
    }
    const appAttrs = {
        name: payload.name ?? "",
    };
    if (payload.namespace !== undefined)
        appAttrs["namespace"] = payload.namespace;
    if (payload.handle !== undefined)
        appAttrs["handle"] = payload.handle;
    if (payload.description !== undefined)
        appAttrs["description"] = payload.description;
    if (payload.icon !== undefined)
        appAttrs["icon"] = payload.icon;
    if (payload.color !== undefined)
        appAttrs["color"] = payload.color;
    if (payload.commentsEnabled !== undefined)
        appAttrs["comments_enabled"] = payload.commentsEnabled;
    if (payload.lockStages !== undefined)
        appAttrs["lock_stages"] = payload.lockStages;
    const categoryName = payload.category?.name;
    if (categoryName !== undefined && categoryName !== "") {
        const category = ctx.orgRefs.byName(CATEGORY_ORG_BAG, categoryName);
        if (category === undefined) {
            ctx.diagnostics.push(missingCategoryDiagnostic(categoryName));
        }
        else {
            appAttrs["category_id"] = categoryIdExpr(category);
        }
    }
    const cloudLink = payload.cloudLinkId;
    if (cloudLink !== undefined) {
        const tsLabel = cloudLink.refName ?? "";
        const resolved = ctx.orgRefs.byTsLabel(CLOUD_LINK_ORG_BAG, tsLabel);
        if (resolved === undefined) {
            ctx.diagnostics.push(`cloud link token "${tsLabel}" is not in the org catalog — re-run \`elementum pull org --data-only\``);
        }
        else {
            appAttrs["cloud_link_id"] = expr.dataAttr("elementum_cloudlink", resolved.tfLabel, ["id"]);
        }
    }
    if (payload.cloudOptions !== undefined) {
        ctx.diagnostics.push("cloudOptions are not supported on the terraform path yet; dropped");
    }
    if (payload.displayBlocks !== undefined || payload.recordCreateDisplayBlocks !== undefined) {
        // ei export carries no display-block resources (plan learning #7) — the
        // platform owns layouts on this path.
        ctx.diagnostics.push("display blocks are not supported on the terraform path; dropped");
    }
    // --- Field pass: fold system-tagged fields, emit one resource per custom field.
    const blocks = [];
    const fieldAddresses = new Map();
    const fieldMetadata = new Map();
    const fieldNames = new Map();
    let statusOptions;
    let stages;
    const systemFieldConfig = {};
    const stageTfLabels = new Set();
    const objectId = expr.resourceAttr(APP_RESOURCE_TYPE, ctx.appTfLabel, ["id"]);
    for (const fieldEntry of payload.fields ?? []) {
        const typeKey = Object.keys(fieldEntry)[0];
        if (typeKey === undefined)
            continue;
        const inner = fieldEntry[typeKey];
        const name = inner.name ?? "";
        const fieldKey = inner.__refName ?? snakeSlug(name);
        const subType = SUB_TYPE_BY_TYPE_KEY.get(typeKey);
        if (fieldKey !== "" && name !== "" && subType !== undefined) {
            fieldMetadata.set(fieldKey, {
                name,
                fieldType: subType.authoringType,
                ...(inner.picklistValues !== undefined
                    ? { options: inner.picklistValues.map((value) => picklistLabel(value)) }
                    : {}),
                ...(inner.tags !== undefined ? { tags: inner.tags } : {}),
            });
        }
        if (fieldKey !== "" && name !== "")
            fieldNames.set(fieldKey, name);
        const systemTag = inner.tags?.find((tag) => SYSTEM_FIELD_TAGS.has(tag));
        if (systemTag !== undefined) {
            const systemKey = SYSTEM_FIELD_KEY_BY_TAG[systemTag];
            if (systemKey === undefined) {
                ctx.diagnostics.push(`systemFields: unsupported semantic tag ${systemTag}; validation flags dropped`);
            }
            else {
                systemFieldConfig[SYSTEM_FIELD_HCL_KEY_BY_KEY[systemKey]] = {
                    required: inner.required ?? false,
                    required_on_close: inner.requiredOnClose ?? false,
                    show_on_create: inner.showOnCreate ?? false,
                };
            }
            switch (systemTag) {
                case "TITLE":
                    if (name !== "Title")
                        appAttrs["title_field_name"] = name;
                    if (inner.description !== undefined)
                        appAttrs["title_field_description"] = inner.description;
                    break;
                case "HANDLE":
                    if (name !== "ID")
                        appAttrs["id_field_name"] = name;
                    if (inner.description !== undefined)
                        appAttrs["id_field_description"] = inner.description;
                    break;
                case "STATUS":
                    if (name !== "Status")
                        appAttrs["status_field_name"] = name;
                    if (inner.description !== undefined)
                        appAttrs["status_field_description"] = inner.description;
                    if (inner.picklistValues !== undefined) {
                        // ei's dialect: every status option item carries `tags` (empty
                        // ok); `color` only when set.
                        statusOptions = inner.picklistValues.map((pv) => ({
                            label: picklistLabel(pv),
                            ...(pv.color !== undefined && pv.color !== "" && { color: pv.color }),
                            tags: [...(pv.tags ?? [])],
                        }));
                    }
                    break;
                case "STAGE":
                    if (name !== "Stage") {
                        ctx.diagnostics.push(`systemFields.stage: the provider has no stage field name attribute; authored name "${name}" dropped (field stays "Stage")`);
                    }
                    if (inner.picklistValues !== undefined) {
                        stages = inner.picklistValues.map((pv) => {
                            const label = picklistLabel(pv);
                            const key = snakeSlug(label);
                            stageTfLabels.add(key);
                            return { key, name: label };
                        });
                    }
                    break;
                default: {
                    const defaultName = AUDIT_DEFAULT_NAMES[systemTag];
                    if (defaultName !== undefined && name !== defaultName) {
                        ctx.diagnostics.push(`systemFields: the provider auto-creates the ${systemTag} audit field as "${defaultName}" and has no rename attribute; authored name "${name}" dropped`);
                    }
                    break;
                }
            }
            continue;
        }
        // Custom field → one `elementum_*_field` resource (entities/field).
        const field = fieldToTf(typeKey, inner, {
            ownerTfLabel: ctx.appTfLabel,
            appRefName: ctx.appRefName,
            objectId,
            diagnostics: ctx.diagnostics,
            orgRefs: ctx.orgRefs,
            workspaceAspects: ctx.workspaceAspects,
        });
        if (field === undefined)
            continue;
        blocks.push(field.block);
        fieldAddresses.set(field.bagKey, field.address);
    }
    if (Object.keys(systemFieldConfig).length > 0) {
        appAttrs["system_field_config"] = systemFieldConfig;
    }
    // Render platform defaults explicitly when no status override is authored.
    // The platform creates these values for an empty list, but returning them
    // after apply would violate Terraform's configured list length.
    appAttrs["status_options"] = statusOptions === undefined || statusOptions.length === 0
        ? DEPLOY_DEFAULT_STATUS_OPTION_VALUES.map((option) => ({ ...option, tags: [...option.tags] }))
        : statusOptions;
    if (stages === undefined || stages.length === 0) {
        appAttrs["stages"] = [
            { key: "stage_1", name: "Stage 1" },
            { key: "stage_2", name: "Stage 2" },
        ];
        stageTfLabels.add("stage_1");
        stageTfLabels.add("stage_2");
    }
    else {
        appAttrs["stages"] = stages;
    }
    // --- View pass: layouts / list views / view order (entities/view), owner passed in.
    blocks.push(...dashboardsToTf(payload.dashboards, {
        ownerTfLabel: ctx.appTfLabel,
        scope: "app",
        ownerType: "APP_ASPECT",
        ownerId: objectId,
        ownerRefName: ctx.appRefName,
        ownerResourceType: APP_RESOURCE_TYPE,
        orgRefs: ctx.orgRefs,
        workspaceAspects: ctx.workspaceAspects,
        availableChartRefNames: ctx.workspaceAspects?.get(workspaceAspectKey("app", ctx.appRefName))?.managedChildRefNames?.get("chart"),
        diagnostics: ctx.diagnostics,
    }));
    blocks.push(...widgetsToTf(payload.widgets, {
        ownerRefName: ctx.appRefName,
        ownerTfLabel: ctx.appTfLabel,
        ownerType: APP_RESOURCE_TYPE,
        scope: "app",
        objectId,
        orgRefs: ctx.orgRefs,
        workspaceAspects: ctx.workspaceAspects,
        diagnostics: ctx.diagnostics,
        fieldAddresses,
        relationshipTargets: relationshipTargetsFromBag(payload.relationships),
    }));
    const { blocks: viewBlocks } = viewToTf(payload.layouts, payload.listViews, payload.calendarViews, payload.kanbanViews, payload.dashboardViews, payload.agentViews, payload.viewOrder, {
        ownerRefName: ctx.appRefName,
        ownerTfLabel: ctx.appTfLabel,
        aspectName: payload.name ?? "",
        objectId,
        stageTfLabels,
        dashboardKeys: new Set(Object.keys(payload.dashboards ?? {})),
        orgRefs: ctx.orgRefs,
        diagnostics: ctx.diagnostics,
        fieldAddresses,
        widgetKeys: new Set(Object.keys(payload.widgets ?? {})),
    });
    blocks.push(...viewBlocks);
    const recordCreateForm = recordCreateFormToTf(payload.recordCreateForm, {
        ownerRefName: ctx.appRefName,
        ownerTfLabel: ctx.appTfLabel,
        scope: "app",
        objectId,
        diagnostics: ctx.diagnostics,
        fieldAddresses,
    });
    if (recordCreateForm !== undefined)
        blocks.push(recordCreateForm);
    blocks.push(...dynamicLayoutsToTf(payload.dynamicLayouts, {
        ownerRefName: ctx.appRefName,
        ownerTfLabel: ctx.appTfLabel,
        objectId,
        diagnostics: ctx.diagnostics,
        orgRefs: ctx.orgRefs,
        workspaceAspects: ctx.workspaceAspects,
        fieldAddresses,
    }));
    blocks.push(...relationshipsToTf(payload.relationships, {
        ownerRefName: ctx.appRefName,
        ownerTfLabel: ctx.appTfLabel,
        ownerType: "elementum_app",
        scope: "app",
        objectId,
        orgRefs: ctx.orgRefs,
        workspaceAspects: ctx.workspaceAspects,
        diagnostics: ctx.diagnostics,
    }));
    // --- Access policy pass (entities/access-policy), owner passed in.
    // Authored entries only. Creating an app also has the platform mint a
    // creator policy (userIds = [you]) that is NOT in this payload — pull
    // will see it; we never emit it here.
    for (const [index, entry] of (payload.accessPolicies ?? []).entries()) {
        const { block } = accessPolicyToTf(entry, index, {
            ownerTfLabel: ctx.appTfLabel,
            scope: "app",
            objectId,
            orgRefs: ctx.orgRefs,
            diagnostics: ctx.diagnostics,
            appRefName: ctx.appRefName,
            serviceAccounts: payload.serviceAccounts,
            fieldAddresses,
        });
        blocks.push(block);
    }
    blocks.push(...rolesToTf(payload.roles, {
        ownerRefName: ctx.appRefName,
        ownerTfLabel: ctx.appTfLabel,
        scope: "app",
        objectId,
        serviceAccounts: payload.serviceAccounts,
        orgRefs: ctx.orgRefs,
        diagnostics: ctx.diagnostics,
    }));
    blocks.push(...serviceAccountsToTf(payload.serviceAccounts, {
        ownerTfLabel: ctx.appTfLabel,
        appId: objectId,
        roles: payload.roles,
        orgRefs: ctx.orgRefs,
        diagnostics: ctx.diagnostics,
    }));
    blocks.unshift({ kind: "resource", type: APP_RESOURCE_TYPE, label: ctx.appTfLabel, attrs: appAttrs });
    return { blocks, fieldAddresses, fieldNames, fieldMetadata };
}
